//! SwordState: CombatClass states (sheet T00038; names inferred).
//!
//! Generated by `python tools/gen_enum.py T00038 SwordState ...` from sheet/enums.tsv; do not edit.

/// @type SwordState
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(i32)]
pub enum SwordState {
    Attack = 0,
    Block = 1,
    Engaged = 3,
    Idle = 4,
    Circle = 5,
    Waiting = 6,
    Locked = 8,
    TargetLost = 9,
    Disengage = 10,
    Disengage2 = 11,
}

impl SwordState {
    pub fn from_i32(v: i32) -> Option<Self> {
        Some(match v {
            0 => Self::Attack,
            1 => Self::Block,
            3 => Self::Engaged,
            4 => Self::Idle,
            5 => Self::Circle,
            6 => Self::Waiting,
            8 => Self::Locked,
            9 => Self::TargetLost,
            10 => Self::Disengage,
            11 => Self::Disengage2,
            _ => return None,
        })
    }

    /// The name as in the sheet (the FCS schema name).
    pub fn name(self) -> &'static str {
        match self {
            Self::Attack => "ATTACK",
            Self::Block => "BLOCK",
            Self::Engaged => "ENGAGED",
            Self::Idle => "IDLE",
            Self::Circle => "CIRCLE",
            Self::Waiting => "WAITING",
            Self::Locked => "LOCKED",
            Self::TargetLost => "TARGET_LOST",
            Self::Disengage => "DISENGAGE",
            Self::Disengage2 => "DISENGAGE_2",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_sheet() {
        let sheet = include_str!("../../sheet/enums.tsv");
        let mut n = 0;
        for line in sheet.lines().filter(|l| l.starts_with("T00038\t")) {
            let f: Vec<&str> = line.split('\t').collect();
            let v: i32 = f[2].parse().unwrap();
            let t = SwordState::from_i32(v)
                .unwrap_or_else(|| panic!("sheet value {v} missing in enum"));
            assert_eq!(t.name(), f[1]);
            assert_eq!(t as i32, v);
            n += 1;
        }
        assert_eq!(n, 10, "enum and sheet differ in size");
    }
}
